<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue'
import {api,protectedObjectUrl} from './api'
const props=defineProps<{assetId:number;sourceId:number;revision:number;disabled?:boolean}>()
const emit=defineEmits<{insert:[marker:string]}>()
const url=ref(''),error=ref(''),busy=ref(false),start=ref<number[]|null>(null),end=ref<number[]|null>(null),dragging=ref(false)
let controller:AbortController|undefined
const box=computed(()=>start.value&&end.value?[Math.min(start.value[0],end.value[0]),Math.min(start.value[1],end.value[1]),Math.max(start.value[0],end.value[0]),Math.max(start.value[1],end.value[1])]:null)
const imageRatio=ref(1)
function imageLoaded(event:Event){const image=event.target as HTMLImageElement;imageRatio.value=image.naturalWidth/image.naturalHeight}
const coordinates=ref([0,0,1000,1000])
function updateBox(index:number,event:Event){const value=Number((event.target as HTMLInputElement).value);if(!Number.isFinite(value))return;coordinates.value[index]=Math.round(Math.max(0,Math.min(1000,value)));const [left,top,right,bottom]=coordinates.value;start.value=[left!,top!];end.value=[right!,bottom!]}
function wholePage(){coordinates.value=[0,0,1000,1000];start.value=[0,0];end.value=[1000,1000]}
const previewStyle=computed(()=>box.value?{width:100000/(box.value[2]-box.value[0])+'%',maxWidth:'none',transform:`translate(-${box.value[0]/10}%,-${box.value[1]/10}%)`}: {})
const previewRatio=computed(()=>box.value?String(imageRatio.value*(box.value[2]-box.value[0])/(box.value[3]-box.value[1])):undefined)
const overlay=computed(()=>box.value?{left:box.value[0]/10+'%',top:box.value[1]/10+'%',width:(box.value[2]-box.value[0])/10+'%',height:(box.value[3]-box.value[1])/10+'%'}:{})
watch(()=>props.assetId,async()=>{controller?.abort();controller=new AbortController();const current=controller;if(url.value)URL.revokeObjectURL(url.value);url.value='';coordinates.value=[0,0,1000,1000];imageRatio.value=1;start.value=null;end.value=null;error.value='';try{const result=await protectedObjectUrl(`/api/question-assets/${props.assetId}/`,current.signal);if(current.signal.aborted)URL.revokeObjectURL(result);else url.value=result}catch{if(!current.signal.aborted)error.value='原卷图片读取失败'}},{immediate:true})
function point(event:PointerEvent){const r=(event.currentTarget as HTMLElement).getBoundingClientRect();return [Math.round(Math.max(0,Math.min(1000,(event.clientX-r.left)/r.width*1000))),Math.round(Math.max(0,Math.min(1000,(event.clientY-r.top)/r.height*1000)))]}
function down(event:PointerEvent){if(props.disabled||busy.value)return;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);start.value=point(event);end.value=point(event);dragging.value=true}
function move(event:PointerEvent){if(dragging.value){end.value=point(event);if(box.value)coordinates.value=[...box.value]}}
async function crop(){if(!box.value||props.disabled||busy.value)return;busy.value=true;error.value='';try{const result=await api<{marker:string}>(`exam-sources/${props.sourceId}/`,'POST',{action:'crop',asset_id:props.assetId,box:box.value,expected_revision:props.revision});emit('insert',result.marker);start.value=null;end.value=null}catch(e){error.value=e instanceof Error?e.message:'裁剪失败'}finally{busy.value=false}}
onUnmounted(()=>{controller?.abort();if(url.value)URL.revokeObjectURL(url.value)})
</script>
<template><section class="paper-cropper"><p>在原卷上拖动框选配图，再插入所选位置。请保留图形边缘的字母、数字和单位，避开答案和其他题目。可用下方坐标微调，再检查预览。</p><div v-if="url" class="crop-surface" @pointerdown="down" @pointermove="move" @pointerup="dragging=false" @pointercancel="dragging=false"><img :src="url" alt="试卷原页，可拖动框选配图" draggable="false" @load="imageLoaded"><span v-if="box" class="crop-selection" :style="overlay"></span></div><p v-else-if="!error" role="status">正在读取原卷图片…</p><fieldset v-if="url" :disabled="disabled||busy"><legend>精确调整范围（0–1000，从左上角计）</legend><label v-for="(label,i) in ['左边界','上边界','右边界','下边界']" :key="i">{{label}}<input type="number" min="0" max="1000" step="1" :value="coordinates[i]" :aria-label="label" @input="updateBox(i,$event)"></label><button type="button" class="secondary" @click="wholePage">从整页重新框选</button></fieldset><section v-if="url&&box&&box[2]>box[0]&&box[3]>box[1]" class="crop-preview"><h5>裁剪预览</h5><div class="crop-preview-window" :style="{aspectRatio:previewRatio}"><img :src="url" :style="previewStyle" alt="当前框选区域预览"></div><p>插入前确认边缘标注完整。预览包含不应公开的答案时，请缩小范围；整页不要直接作为题图发布。</p></section><button class="secondary" :disabled="disabled||busy||!box||box[2]-box[0]<5||box[3]-box[1]<5" @click="crop">{{busy?'正在裁剪…':'裁剪并插入所选位置'}}</button><p v-if="error" role="alert">{{error}}</p></section></template>
<style scoped>.crop-surface{position:relative;touch-action:none;user-select:none;cursor:crosshair}.crop-surface img{display:block;width:100%;height:auto;pointer-events:none}.crop-selection{position:absolute;border:2px solid #a60000;background:#a6000025;pointer-events:none;box-sizing:border-box}.paper-cropper fieldset{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;border:1px solid #d5e0db;margin-top:10px;min-width:0}.paper-cropper label{display:grid;gap:4px}.paper-cropper input{width:100%;min-width:0;box-sizing:border-box}.crop-preview-window{overflow:hidden;position:relative;width:100%;border:1px solid #d5e0db}.crop-preview-window img{display:block;height:auto;transform-origin:top left}.crop-preview h5{margin:12px 0 6px}.paper-cropper p{font-size:12px;line-height:1.6}.paper-cropper button{margin-top:8px}</style>
